const touchgfx::TypedText::TypedTextData* const typedTextDatabaseArray[] = {
    typedText_database_GB
};

namespace TypedTextDatabase
{
const touchgfx::TypedText::TypedTextData* getInstance(touchgfx::LanguageId id)
{
    return typedTextDatabaseArray[id];
}

uint16_t getInstanceSize()
{
    return sizeof(typedText_database_DEFAULT) / sizeof(touchgfx::TypedText::TypedTextData);
}

const touchgfx::Font** getFonts()
{
    return touchgfx_fonts;
}

const touchgfx::Font* setFont(touchgfx::FontId fontId, const touchgfx::Font* font)
{
    const touchgfx::Font* old = touchgfx_fonts[fontId];
    touchgfx_fonts[fontId] = font;
    return old;
}

void resetFont(touchgfx::FontId fontId)
{
    switch (fontId)
    {
    case 0:
        touchgfx_fonts[0] = &(getFont_verdana_20_4bpp());
        break;
    case 1:
        touchgfx_fonts[1] = &(getFont_verdana_40_4bpp());
        break;
    case 2:
        touchgfx_fonts[2] = &(getFont_verdana_13_4bpp());
        break;
    case 3:
        touchgfx_fonts[3] = &(getFont_arial_64_4bpp());
        break;
    case 4:
        touchgfx_fonts[4] = &(getFont_GOTHICB_TTF_35_4bpp());
        break;
    case 5:
        touchgfx_fonts[5] = &(getFont_TCCEB_TTF_27_4bpp());
        break;
    case 6:
        touchgfx_fonts[6] = &(getFont_arial_180_4bpp());
        break;
    case 7:
        touchgfx_fonts[7] = &(getFont_arial_62_4bpp());
        break;
    case 8:
        touchgfx_fonts[8] = &(getFont_GOTHICB_TTF_24_4bpp());
        break;
    case 9:
        touchgfx_fonts[9] = &(getFont_DejaVuSansMono_22_4bpp());
        break;
    case 10:
        touchgfx_fonts[10] = &(getFont_ROCKB_TTF_85_4bpp());
        break;
    case 11:
        touchgfx_fonts[11] = &(getFont_GOTHICB_TTF_50_4bpp());
        break;
    case 12:
        touchgfx_fonts[12] = &(getFont_GOTHICB_TTF_20_4bpp());
        break;
    case 13:
        touchgfx_fonts[13] = &(getFont_verdana_16_4bpp());
        break;
    case 14:
        touchgfx_fonts[14] = &(getFont_SCHLBKB_TTF_18_4bpp());
        break;
    }
}
} // namespace TypedTextDatabase
